string.match:
(value) => {
    expression.lastIndex = 0
    const result = value.match(expression)
    return result === null ? none : some(result)
  }

string.truncate:
(value) => {
    const bound = Math.max(0, Math.trunc(maximum))
    if (value.length <= bound) return value
    if (bound <= omission.length) return omission.slice(0, bound)
    return value.slice(0, bound - omission.length) + omission
  }

object.pick:
(value) => {
    const output = Object.create(null) as object
    for (const key of selected) {
      if (hasOwn(value, key) && isEnumerable(value, key)) {
        define(output, key, Reflect.get(value, key))
      }
    }
    return output as any
  }

object.omit:
(value) => {
    const excluded = new Set<PropertyKey>(omitted)
    const output = Object.create(null) as object
    for (const key of enumerableKeys(value)) {
      if (!excluded.has(key)) define(output, key, Reflect.get(value, key))
    }
    return output as any
  }

object.assoc:
(value) => {
    const output = cloneEnumerable(value)
    define(output, key, replacement)
    return output as any
  }

object.dissoc:
(value) => {
  const output = Object.create(Object.getPrototypeOf(value)) as object
  for (const current of enumerableKeys(value)) {
    if (current !== key) define(output, current, Reflect.get(value, current))
  }
  return output as any
}

object.mapValues:
(value) => {
    const output = Object.create(null) as object
    for (const key of enumerableKeys(value)) {
      define(output, key, f(Reflect.get(value, key) as any, key as any))
    }
    return output as any
  }

object.mapKeys:
(value) => {
    const output = Object.create(null) as object
    for (const key of enumerableKeys(value)) {
      const current = Reflect.get(value, key)
      define(output, f(key as any, current as any), current)
    }
    return output as any
  }

object.pickBy:
(value) => {
    const output = Object.create(null) as object
    for (const key of enumerableKeys(value)) {
      const current = Reflect.get(value, key)
      if (predicate(current as any, key as any)) define(output, key, current)
    }
    return output as any
  }

object.omitBy:
(value) => {
  const output = Object.create(null) as object
  for (const key of enumerableKeys(value)) {
    const current = Reflect.get(value, key)
    if (!(predicate as any)(current, key)) define(output, key, current)
  }
  return output as any
}

object.mergeWith:
(left) => {
    const output = cloneEnumerable(left)
    for (const key of enumerableKeys(right)) {
      const rightValue = Reflect.get(right, key)
      define(
        output,
        key,
        hasOwn(left, key) ? resolve(Reflect.get(left, key), rightValue, key as any) : rightValue,
      )
    }
    return output as any
  }

object.getPathOrUndefined:
(value) => {
  let current: unknown = value
  for (const key of path) {
    if (current === null || (typeof current !== 'object' && typeof current !== 'function')) {
      return undefined
    }
    if (!hasOwn(current, key)) return undefined
    current = Reflect.get(current, key)
  }
  return current as any
}

object.hasPath:
(value) => {
  let current: unknown = value
  for (const key of path) {
    if (current === null || (typeof current !== 'object' && typeof current !== 'function')) {
      return false
    }
    if (!hasOwn(current, key)) return false
    current = Reflect.get(current, key)
  }
  return true
}

object.evolve:
(value) => {
    const output = cloneEnumerable(value)
    for (const key of enumerableKeys(transformations)) {
      if (!hasOwn(value, key)) continue
      const transform = Reflect.get(transformations, key) as
        | ((current: unknown) => unknown)
        | undefined
      if (transform) define(output, key, transform(Reflect.get(value, key)))
    }
    return output
  }

number.clamp:
(value) => {
    const low = Math.min(minimum, maximum)
    const high = Math.max(minimum, maximum)
    return Math.min(Math.max(value, low), high)
  }

number.between:
(value) => {
    const low = Math.min(minimum, maximum)
    const high = Math.max(minimum, maximum)
    return value >= low && value <= high
  }

number.weightedMeanOrUndefined:
(values) => {
    if (values.length !== weights.length) {
      throw new RangeError('weightedMean: values and weights must have equal lengths')
    }
    let weighted = 0
    let totalWeight = 0
    for (let index = 0; index < values.length; index++) {
      weighted += values[index] * weights[index]
      totalWeight += weights[index]
    }
    return totalWeight === 0 ? undefined : weighted / totalWeight
  }

number.weightedMean:
(values) => {
    const value = weightedMeanOrUndefined(weights)(values)
    return value === undefined ? none : some(value)
  }

number.quantileOrUndefined:
(values) => {
  if (q < 0 || q > 1 || Number.isNaN(q)) {
    throw new RangeError('quantile: q must be in the inclusive range [0, 1]')
  }
  return interpolateSorted(values, q)
}

number.quantile:
(values) => {
    const value = quantileOrUndefined(q)(values)
    return value === undefined ? none : some(value)
  }

number.percentileOrUndefined:
(values) => {
  if (p < 0 || p > 100 || Number.isNaN(p)) {
    throw new RangeError('percentile: p must be in the inclusive range [0, 100]')
  }
  return interpolateSorted(values, p / 100)
}

number.percentile:
(values) => {
    const value = percentileOrUndefined(p)(values)
    return value === undefined ? none : some(value)
  }

number.dotProduct:
(left) => {
    if (left.length !== right.length) {
      throw new RangeError('dotProduct: vectors must have equal lengths')
    }
    let total = 0
    for (let index = 0; index < left.length; index++) total += left[index] * right[index]
    return total
  }

number.dotProductTruncate:
(left) => {
  const length = Math.min(left.length, right.length)
  let total = 0
  for (let index = 0; index < length; index++) total += left[index] * right[index]
  return total
}

number.gcd:
(left) => {
  let a = Math.abs(Math.trunc(left))
  let b = Math.abs(Math.trunc(right))
  while (b !== 0) {
    const remainder = a % b
    a = b
    b = remainder
  }
  return a
}

number.roundTo:
(value) => {
    const factor = 10 ** Math.trunc(digits)
    return Math[mode](value * factor) / factor
  }
